import java.text.Normalizer;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * A filter over the customer list: a name search and a set of statuses to
 * restrict to.
 *
 * <p>Name matching splits {@link #name} on whitespace into terms; a customer
 * matches when every term appears as a substring of either the first or last
 * name, ignoring case and accents. An empty name matches every customer.
 *
 * <p>Status matching restricts to {@link #statuses} when non-empty; an empty
 * set matches every status.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
    private static final Pattern DIACRITICS = Pattern.compile("\\p{M}+");

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    /** Whether {@code customer} satisfies both the name and status filter. */
    public boolean matches(Customer customer) {
        return matchesName(customer) && matchesStatus(customer);
    }

    private boolean matchesName(Customer customer) {
        List<String> terms = nameTerms();
        if (terms.isEmpty()) {
            return true;
        }
        String first = normalize(customer.firstName());
        String last = normalize(customer.lastName());
        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private List<String> nameTerms() {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return List.of();
        }
        return WHITESPACE.splitAsStream(trimmed).map(CustomerFilter::normalize).toList();
    }

    private static String normalize(String value) {
        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
        return DIACRITICS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
    }
}
